  "entries": [
    {
      "name_han": "冥报记",
      "logic_thesis": "善恶行为必然在幽冥司法体系中被记账、审判与兑现，现世吉凶是冥报的可见结果；道德因果具有可验证的案例结构。",
      "logic_chain": "1) 人的言行在阳世留下业因；2) 冥府以簿籍与吏卒记录并核验；3) 审判按罪福轻重处分；4) 报应可表现为寿夭、疾病、官讼或救护；5) 实录式叙述使因果成为可劝诫的证据；6) 故修善避恶是改变结局的主动杠杆。",
      "logic_practice": "1) 先定日主善恶倾向：印比主护持，官杀/食伤过旺主刑责摩擦；2) 查官杀与驿马、天罗地网、羊刃等组合论官非病灾；3) 用岁运冲合官杀验“报至之年”；4) 见印星通关、天乙贵人、华盖可作“善业抵消”信号；5) 大运由杀重转印比，断为改过积德后的转运节点。",
      "logic_compare": "较《冥祥记》更偏唐代“冥府司法—地狱审讯”的制度化报应，劝诫语气更强。《冤魂志》重冤魂索命，本书更强调簿籍、对质与慎刑式正义。"
    },
    {
      "name_han": "续玄怪录",
      "logic_thesis": "人生际遇多由前定气数与隐秘契约推动，奇遇与变故揭示命数先于人为算计；人可在既定格局中以德行与选择微调结局。",
      "logic_chain": "1) 异常事件暴露命运脚本已写定；2) 神鬼仙吏或谶示是脚本的传讯者；3) 个人欲望常与既定气数冲突；4) 顺从或违抗会放大福祸差；5) 文学化叙事把命数从抽象变为可感情节；6) 觉悟者能以节制与信诺减少反噬。",
      "logic_practice": "1) 以日主与年月气势定“主脚本”（格局成败）；2) 用驿马、桃花、华盖、空亡抓奇遇与非常之变；3) 岁运引动命中伏神（藏干、合冲）断突然转折；4) 看食伤制杀或印化杀，判人在气数中的主动回旋空间；5) 忌神得势之运勿强求名利，宜守信止损。",
      "logic_compare": "较六朝短制志怪更接近唐传奇：情节完整、命定感强。比《玄怪录》更常展开前定与再续缘，比《冥报记》少地狱司法、多气数与奇遇。"
    },
    {
      "name_han": "续齐谐记",
      "logic_thesis": "人与物、人与神、亲族之间存在可感的感应 reciprocal 秩序：恩必报、义必续、亵渎神物必受反噬。",
      "logic_chain": "1) 善行（救雀、护物、敦亲）启动感应力；2) 神物、异兽、精魄成为媒介；3) 回报以贵物、信息或护佑显现；4) 破坏亲族和合或侵夺灵物则触发诅咒式反报；5) 岁时神异（牛女渡河）显示宇宙节律约束人事；6) 故伦理与礼敬是趋吉的操作层。",
      "logic_practice": "1) 看比劫与印星论亲族和合与兄弟助力；2) 食伤生财逢贵人，断“恩德—回报”链条；3) 财星被劫或神煞（亡神、劫煞）加临，防侵夺反噬；4) 以月令与七政岁时对应节日节点（如七夕类驿马桃花运）；5) 合多而冲少之岁，宜修人情、忌毁约。",
      "logic_compare": "承《齐谐》志怪传统，偏短小灵验与伦理寓言，少大规模地狱叙事。比《搜神记》更精炼，比《冥报记》更重人情报恩与岁时神话。"
    },
    {
      "name_han": "仙传拾遗",
      "logic_thesis": "成仙是长期修真、隐德与气化升格的结果：去浊留清、积功累行，则形神可超越普通寿限与社会轨迹。",
      "logic_chain": "1) 常人困于浊气与欲望；2) 师承、方术与戒行净化身心；3) 隐德与济物积累“仙资”；4) 气满神凝表现为异象与长生征兆；5) 白日飞升或尸解是格局完成式；6) 故命中清气与修行时运决定可达高度。",
      "logic_practice": "1) 日主得清气（印比通根、财官有情而不浊）论仙道根器；2) 华盖、天德、月德、空亡在闲位可作出世倾向；3) 食伤泄秀而官杀不迫，宜术数艺术修持；4) 大运由浊财官转入印比或食伤秀气，断修真窗口；5) 忌神为湿浊困印时，先去病气再言升华。",
      "logic_compare": "属杜光庭一系道教仙传，比《列仙传》更系统、故事更繁。《神仙传》重道术奇迹，本书更强调隐德、谱系与拾遗式补全圣传。"
    },
    {
      "name_han": "五行大义",
      "logic_thesis": "五行是造化根源与人伦资始：由阴阳散为精象，经干支、生克、刑德、情性诸层，可统一解释天象、身体、政治与命运。",
      "logic_chain": "1) 阴阳动静生五行；2) 干支配位使五行可计算；3) 生克杂合规定万物关系；4) 德、刑、合、冲是奖惩机制；5) 情性、治政、诸神皆五行映射；6) 掌握结构即可由象推数、由数断事。",
      "logic_practice": "1) 先定日主与月令旺衰，标定五行力量；2) 按相生相克与杂气定喜用忌仇；3) 引入刑、冲、合、害、德论关系质量；4) 以十二长生与支藏干细化用神层次；5) 岁运加减五行量，预测情性与事件方向；6) 参照神煞仅作辅证，主断仍归生克刑德。",
      "logic_compare": "隋前五行理论的系统总结，比《月令》类时令书更抽象完整，比单纯《子平》口诀更重宇宙论根基。是连接汉纬、术数与后世命理的枢纽文本。"
    },
    {
      "name_han": "古楼观紫云衍庆集",
      "logic_thesis": "圣教兴衰系于圣地、圣师与圣典的连续授受：楼观作为老子授经原点，其兴复即玄教气运的可见化。",
      "logic_chain": "1) 道显于特定时空交汇（终南楼观）；2) 尹喜迎气、二经授受确立法统；3) 宫观碑记与皇权护持巩固法脉；4) 兵燹废圮是气数低潮；5) 重修衍庆是紫气再临的集体工程；6) 故护持祖庭即护持道运。",
      "logic_practice": "1) 以长生帝旺与禄刃所在论“祖地/根基”是否稳；2) 印星为道统与师承，印受损则法脉受阻；3) 驿马合印主迁居名山或入道门；4) 岁运建筑类神（土多有情、官印相生）断修造开光吉时；5) 空亡冲印之年忌轻废坛庙与背师。",
      "logic_compare": "非志怪小说，而是楼观道圣地文献汇编，逻辑是法统—圣地—中兴。比一般仙传更重历史碑刻与制度延续，比《混元圣纪》更聚焦楼观一地。"
    },
    {
      "name_han": "列异传",
      "logic_thesis": "异常并非妄诞，而是天道与幽明对人事的示警与显影；记录异象即保存可解读的征兆系统。",
      "logic_chain": "1) 常态破裂处出现异物异事；2) 异象与人事祸福存在对应；3) 鬼神可介入可视世界；4) 早期志怪以“传”立真；5) 征兆先于大变；6) 善读者由异知常、由常防变。",
      "logic_practice": "1) 命中忌神突现、四柱刑冲剧烈者优先察异兆年；2) 以华盖、阴差、亡神、劫煞作非常事件提示；3) 岁运天克地冲、三刑会聚断异常高发；4) 印比护身则异而不伤，忌神攻身则异化为灾；5) 把梦、怪、病作为流年应期的旁证而非主断。",
      "logic_compare": "魏晋可考较早的志怪专书传统之一，篇幅短、门类杂，开“异可作为证据”的写法。比《搜神记》规模小，比《冥报记》少系统佛教劝惩。"
    },
    {
      "name_han": "幽明录",
      "logic_thesis": "幽界与明界相互贯通：人、鬼、神、仙共享一套可往来的空间伦理，命运在两界交通中展开。",
      "logic_chain": "1) 死生只是界域转换；2) 情感、债务与誓约可跨界延续；3) 洞穴、梦寐、庙祀是通道；4) 人的选择在两界同时记分；5) 题材广及爱情、仙境、冤对；6) 故理解命运须同时读阳德与阴债。",
      "logic_practice": "1) 日支与夫妻宫论人缘跨界（正偏财/官杀质量）；2) 空亡、华盖、沐浴看梦感与非常通道；3) 官杀混杂主阴债官非，印星化解主超度救护；4) 大运入墓库、沐浴、死绝，慎鬼债旧怨；5) 合动夫妻宫之岁，防人鬼情债类纠葛。",
      "logic_compare": "刘义庆志怪代表，比《冥祥记》宣佛色彩淡、题材更广。比《搜神记》更文人化，人鬼恋与洞天叙事突出，因果劝惩不是唯一主轴。"
    },
    {
      "name_han": "甄异传",
      "logic_thesis": "怪异须经甄别核验：真异可征、伪妄须斥，认识秩序建立在“辨真伪—定含义—决去取”之上。",
      "logic_chain": "1) 世间传闻鱼龙混杂；2) 亲历、旁证、应验是甄别标准；3) 真异对应真实气机；4) 伪异来自误读或附会；5) 甄定后方可指导行为；6) 怀疑与取证是理性命数观的前提。",
      "logic_practice": "1) 断事前先核四柱信息是否自洽（干支、纳音、神煞不互相否定）；2) 用神有力且岁运引动方作真应；3) 孤证神煞或单一异事不作铁口；4) 三合三会成局、重复应期出现再定论；5) 矛盾组合先求通关，再判吉凶层级。",
      "logic_compare": "六朝志怪中突出“甄”的认识论姿态，较《列异传》更强调辨析。比佛教辅教书少独断劝惩，更接近经验核验传统。"
    },
    {
      "name_han": "冥祥记",
      "logic_thesis": "虔信与称念能感通圣力（尤观世音），使信徒在危难、无嗣、地狱怖畏中获得可验证的救护与祥瑞。",
      "logic_chain": "1) 苦难暴露众生无自救；2) 一心称念建立感通；3) 菩萨或瑞应介入转折；4) 地狱示现强化戒惧；5) 个人经历（作者受戒感通）作信度基础；6) 信仰行为本身成为改命操作。",
      "logic_practice": "1) 印星与贵人为“他力救护”主星；2) 官杀攻身而无印，主危难需外援；3) 天乙、天德、月德、文昌加临印比，断祈请易应；4) 流年劫煞羊刃并见时启动“急难—求助”课；5) 食伤生财有制可作还愿、修庙、布施之运。",
      "logic_compare": "典型释氏辅教志怪，核心是观音应验与地狱劝惩，比《冥报记》更早、更重称名感通。比《幽明录》劝信目的更专一，文学趣味让位于灵验证明。"
    }
  ]
}
